<div class="branches-workspace">
<section class="admin-page-head"><div><p class="admin-kicker">SUCURSALES</p><h1>Sucursales</h1><p>Administra los datos de contacto y operación de cada ubicación.</p></div><?php if ($capabilities['branches.create'] ?? false): ?><a class="admin-primary-button" data-admin-form-link href="/admin/branches/create">+ Nueva sucursal</a><?php endif ?></section>
<section class="admin-panel admin-table-panel branches-directory"><?php if ($page->items === []): ?><div class="branches-empty"><h2>Aún no hay sucursales registradas</h2><p>Registra sus datos de contacto y confirma la ubicación en el mapa.</p><?php if($capabilities['branches.create']??false):?><a class="admin-primary-button" data-admin-form-link href="/admin/branches/create">Registrar primera sucursal</a><?php endif?></div><?php else: ?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Sucursal</th><th>Contacto</th><th>Estado</th><th><span class="sr-only">Acciones</span></th></tr></thead><tbody><?php foreach ($page->items as $branch): ?><tr><td><div><strong><?= e($branch->name) ?></strong><small><?= e($branch->code) ?></small></div></td><td><div><?= e($branch->email ?? 'Sin correo') ?><small><?= e($branch->phone ?? 'Sin teléfono') ?></small></div></td><td><span class="admin-status <?= $branch->active ? 'is-active' : '' ?>"><?= $branch->active ? 'Activa' : 'Inactiva' ?></span></td><td class="admin-actions"><a class="admin-row-action is-view" data-admin-form-link href="/admin/branches/detail?id=<?= e($branch->id) ?>"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.5"/></svg><span>Consultar</span></a><?php if ($capabilities['branches.edit'] ?? false): ?><a class="admin-row-action is-edit" data-admin-form-link href="/admin/branches/edit?id=<?= e($branch->id) ?>"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 5 5 5M4 20l3.5-.8L19 7.7a2.1 2.1 0 0 0-3-3L4.8 16.2 4 20Z"/></svg><span>Editar</span></a><?php endif ?><?php if ($capabilities['branches.status'] ?? false): ?><form method="post" action="/admin/branches/status"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= e($branch->id) ?>"><input type="hidden" name="active" value="<?= $branch->active ? '0' : '1' ?>"><button class="admin-quiet-button" type="submit" data-confirm-title="<?= $branch->active ? 'Desactivar sucursal' : 'Activar sucursal' ?>" data-confirm="<?= $branch->active ? '¿Desactivar esta sucursal?' : '¿Activar esta sucursal?' ?>" data-confirm-label="<?= $branch->active ? 'Sí, desactivar' : 'Sí, activar' ?>"><?= $branch->active ? 'Desactivar' : 'Activar' ?></button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>

</div>
